import test from 'ava';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement returns customer not found for unknown customer', (t) => {
  const result = statement('UNKNOWN_CUSTOMER', [], '2026-10-07');
  t.is(result.ok, false);
  t.is(result.error, 'CUSTOMER_NOT_FOUND');
});

test('statement with no invoices returns empty list and zero total due', (t) => {
  const result = statement('C-001', [], '2026-10-07');
  t.is(result.ok, true);
  t.deepEqual(result.value.invoices, []);
  t.is(result.value.totalDue, 0);
  t.is(result.value.customerId, 'C-001');
});

test('statement includes only issued and partially_paid invoices', (t) => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'APPLE', qty: 5 }],
  }).value;

  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-02',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const partiallyPaidInv = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-03',
        lines: [{ sku: 'APPLE', qty: 5 }],
      }).value,
      [],
    ).value,
    { amount: 100, date: '2026-10-04' },
  ).value;

  const paidInv = recordPayment(
    recordPayment(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-10-04',
          lines: [{ sku: 'APPLE', qty: 5 }],
        }).value,
        [],
      ).value,
      { amount: 100, date: '2026-10-05' },
    ).value,
    { amount: 13100, date: '2026-10-06' },
  ).value;

  const result = statement('C-001', [draftInv, issuedInv, partiallyPaidInv, paidInv], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 2);
  t.is(result.value.invoices[0].number, issuedInv.number);
  t.is(result.value.invoices[1].number, partiallyPaidInv.number);
});

test('statement includes only invoices for the specified customer', (t) => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-02',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 1);
  t.is(result.value.invoices[0].number, inv1.number);
});

test('statement includes only invoices with issueDate on or before asOf', (t) => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-05',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-10',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv1, inv2, inv3], '2026-10-05');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 2);
  t.is(result.value.invoices[0].issueDate, '2026-10-01');
  t.is(result.value.invoices[1].issueDate, '2026-10-05');
});

test('statement sorts invoices by issueDate', (t) => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-05',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-03',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv1, inv2, inv3], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices[0].issueDate, '2026-10-01');
  t.is(result.value.invoices[1].issueDate, '2026-10-03');
  t.is(result.value.invoices[2].issueDate, '2026-10-05');
});

test('statement includes number, issueDate, dueDate, total, and due for each invoice', (t) => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
      terms: 'NET30',
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 1);

  const stmtInv = result.value.invoices[0];
  t.truthy(stmtInv.number);
  t.is(stmtInv.issueDate, '2026-10-01');
  t.is(stmtInv.dueDate, '2026-10-31');
  t.truthy(typeof stmtInv.total === 'number');
  t.truthy(typeof stmtInv.due === 'number');
});

test('statement calculates due correctly for fully issued invoice', (t) => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices[0].due, result.value.invoices[0].total);
});

test('statement calculates due correctly for partially paid invoice', (t) => {
  const inv = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-01',
        lines: [{ sku: 'APPLE', qty: 5 }],
      }).value,
      [],
    ).value,
    { amount: 500, date: '2026-10-02' },
  ).value;

  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  const stmtInv = result.value.invoices[0];
  const expectedDue = stmtInv.total - 500;
  t.is(stmtInv.due, expectedDue);
});

test('statement calculates totalDue as sum of all dues', (t) => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-02',
        lines: [{ sku: 'APPLE', qty: 3 }],
      }).value,
      [],
    ).value,
    { amount: 500, date: '2026-10-03' },
  ).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-07');
  t.is(result.ok, true);
  const expectedTotalDue = result.value.invoices[0].due + result.value.invoices[1].due;
  t.is(result.value.totalDue, expectedTotalDue);
});

test('statement normalizes customer ID', (t) => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'c-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  // The invoice will have normalized customerId
  t.is(inv.customerId, 'C-001');

  // Query with different casing should still work
  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 1);
});

test('statement with no matching invoices for customer returns empty statement', (t) => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  t.deepEqual(result.value.invoices, []);
  t.is(result.value.totalDue, 0);
});

test('statement returns correct structure', (t) => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = statement('C-001', [inv], '2026-10-07');
  t.is(result.ok, true);
  t.truthy(result.value.customerId);
  t.truthy(Array.isArray(result.value.invoices));
  t.truthy(typeof result.value.totalDue === 'number');
});

