test('statement returns customer not found for unknown customer', (t) => {
  const result = statement('UNKNOWN_CUSTOMER', [], '2026-10-07');
  t.is(result.ok, false);
  t.is(result.error, 'CUSTOMER_NOT_FOUND');
});

test('statement with no invoices returns empty list and zero total due', (t) => {
  const result = statement('C-001', [], '2026-10-07');
  t.is(result.ok, true);
  t.deepEqual(result.value.invoices, []);
  t.is(result.value.totalDue, 0);
  t.is(result.value.customerId, 'C-001');
});

test('statement includes only issued and partially_paid invoices', (t) => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'APPLE', qty: 5 }],
  }).value;

  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-02',
      lines: [{ sku: 'APPLE', qty: 5 }],
    }).value,
    [],
  ).value;

  const partiallyPaidInv = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-03',
        lines: [{ sku: 'APPLE', qty: 5 }],
      }).value,
      [],
    ).value,
    { amount: 100, date: '2026-10-04' },
  ).value;

  const paidInv = recordPayment(
    recordPayment(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-10-04',
          lines: [{ sku: 'APPLE', qty: 5 }],
        }).value,
        [],
      ).value,
      { amount: 100, date: '2026-10-05' },
    ).value,
    { amount: 13100, date: '2026-10-06' },
  ).value;

  const result = statement('C-001', [draftInv, issuedInv, partiallyPaidInv, paidInv], '2026-10-07');
  t.is(result.ok, true);
  t.is(result.value.invoices.length, 2);
  t.is(result.value.invoices[0].number, issuedInv.number);
  t.is(result.value.invoices[1].number, partiallyPaidInv.number);
});

